    const docAtualDe = (p3) => docsDe2(p3).find((d3) => d3.id === (p3 && p3.docAtual)) || docsDe2(p3)[0] || DOC_VAZIO;
    const textoDe = (p3) => docAtualDe(p3).text || "";
    const exDoDoc2 = (p3, docId) => (p3.excerpts || []).filter((e4) => e4.docId === docId);
    const exDoAtual = (p3) => exDoDoc2(p3, docAtualDe(p3).id);
    const textoTodo = (p3) => docsDe2(p3).map((d3) => d3.text || "").join("\n\n");
    const nomeDoc2 = (p3, docId) => (docsDe2(p3).find((d3) => d3.id === docId) || {}).name || "\u2014";
    function exampleProject() {
      const text = `ENTREVISTA \u2014 Experi\xEAncia de trabalho remoto
(participante: profissional, 34 anos; entrevista semiestruturada)

Entrevistador: Como foi para voc\xEA come\xE7ar a trabalhar de casa?
Participante: No come\xE7o foi confuso. Eu n\xE3o tinha um espa\xE7o s\xF3 para o trabalho, ent\xE3o usava a mesa da cozinha. A internet ca\xEDa toda hora e eu perdia parte das reuni\xF5es, o que me deixava ansioso. Levei umas tr\xEAs semanas para criar uma rotina que funcionasse.

Entrevistador: E o contato com os colegas, como ficou?
Participante: Senti muita falta da conviv\xEAncia. Antes a gente resolvia as coisas no corredor, r\xE1pido. De casa, tudo virava mensagem ou reuni\xE3o marcada, e eu me senti bastante isolado, principalmente nas primeiras semanas.

Entrevistador: Teve algum ponto positivo?
Participante: Sim, v\xE1rios. Economizei o tempo do deslocamento, que antes eram duas horas por dia, e consegui organizar meu trabalho no meu pr\xF3prio ritmo. Passei a almo\xE7ar com a minha fam\xEDlia, coisa que n\xE3o acontecia havia anos. Essa flexibilidade foi o que mais valorizei.

Entrevistador: E as dificuldades continuaram?
Participante: Algumas sim. Como o computador estava sempre ali, eu acabava trabalhando al\xE9m da hora, respondendo mensagem \xE0 noite. Eram tarefas demais e eu passava o dia inteiro na tela. No fim de alguns meses eu estava exausto, mesmo gostando da liberdade que o modelo trouxe.

Entrevistador: Olhando para tr\xE1s, o que voc\xEA mudaria?
Participante: Eu definiria hor\xE1rios mais claros desde o in\xEDcio e combinaria com a equipe momentos fixos para conversar. O problema n\xE3o foi o trabalho remoto em si, mas a falta de combinados.`;
      const codes = [
        { id: "c1", name: "Dificuldade t\xE9cnica", color: PALETTE2[0], desc: "internet, equipamento, espa\xE7o de trabalho" },
        { id: "c2", name: "Adapta\xE7\xE3o", color: PALETTE2[2], desc: "criar rotina, ajustar-se ao novo modelo" },
        { id: "c3", name: "Isolamento", color: PALETTE2[1], desc: "falta de conv\xEDvio e troca informal" },
        { id: "c4", name: "Flexibilidade", color: PALETTE2[3], desc: "tempo, deslocamento, fam\xEDlia" },
        { id: "c5", name: "Autonomia", color: PALETTE2[5], desc: "organizar o pr\xF3prio trabalho" },
        { id: "c6", name: "Sobrecarga", color: PALETTE2[6], desc: "excesso de jornada e de tela" }
      ];
      const mk = (id, sub, codeIds, memo = "") => {
        const start = text.indexOf(sub);
        return { id, start, end: start + sub.length, text: sub, codeIds, memo };
      };
      const excerpts = [
        mk("e1", "A internet ca\xEDa toda hora e eu perdia parte das reuni\xF5es", ["c1"], "problema de acesso"),
        mk("e2", "Levei umas tr\xEAs semanas para criar uma rotina", ["c2"]),
        mk("e3", "me senti bastante isolado, principalmente nas primeiras semanas", ["c3"]),
        mk("e4", "Economizei o tempo do deslocamento, que antes eram duas horas por dia", ["c4"]),
        mk("e5", "consegui organizar meu trabalho no meu pr\xF3prio ritmo", ["c5"]),
        mk("e6", "Essa flexibilidade foi o que mais valorizei", ["c4"], "valor central para o participante"),
        mk("e7", "eu acabava trabalhando al\xE9m da hora, respondendo mensagem \xE0 noite", ["c6"]),
        mk("e8", "Eram tarefas demais e eu passava o dia inteiro na tela", ["c6", "c1"], "sobrecarga ligada \xE0 tela")
      ];
      const categories = [
        { id: "k1", name: "Desafios da transi\xE7\xE3o", tipo: "emergente", desc: "o que dificultou a mudan\xE7a para o remoto", codeIds: ["c1", "c2", "c3", "c6"] },
        { id: "k2", name: "Ganhos percebidos", tipo: "emergente", desc: "o que o participante passou a valorizar", codeIds: ["c4", "c5"] }
      ];
      const metatexts = [
        { id: "m1", title: "Desafios da transi\xE7\xE3o", categoryId: "k1", body: "Os relatos descrevem uma transi\xE7\xE3o inicialmente custosa para o trabalho remoto: problemas t\xE9cnicos de acesso, a necessidade de construir uma rotina nova, a perda do conv\xEDvio informal e, mais adiante, a sobrecarga ligada ao tempo de tela. Este \xE9 um rascunho de exemplo: substitua por sua pr\xF3pria interpreta\xE7\xE3o, apoiada nos recortes." }
      ];
      return { id: uid4(), name: "Exemplo: entrevista (trabalho remoto)", method: "conteudo", isExample: true, text, codes, excerpts, categories, metatexts, updated: Date.now() };
    }
    function exampleCodingB() {
      const base = exampleProject();
      const text = base.text;
      const codes = base.codes.map((c4) => ({ ...c4 }));
      const mk = (id, sub, codeIds) => {
        const start = text.indexOf(sub);
        return { id, start: start < 0 ? 0 : start, end: start < 0 ? 0 : start + sub.length, text: sub, codeIds, memo: "" };
      };
      const excerpts = [
        mk("b1", "A internet ca\xEDa toda hora e eu perdia parte das reuni\xF5es", ["c1"]),
        mk("b2", "Levei umas tr\xEAs semanas para criar uma rotina que funcionasse", ["c2"]),
        // limite maior que A
        mk("b3", "me senti bastante isolado", ["c3"]),
        // limite menor que A
        mk("b4", "Economizei o tempo do deslocamento, que antes eram duas horas por dia", ["c4"]),
        mk("b5", "consegui organizar meu trabalho no meu pr\xF3prio ritmo", ["c5"]),
        // (B não marcou "Essa flexibilidade foi o que mais valorizei")
        mk("b7", "eu acabava trabalhando al\xE9m da hora, respondendo mensagem \xE0 noite", ["c6"]),
        mk("b8", "Eram tarefas demais e eu passava o dia inteiro na tela", ["c6"]),
        // A usou c6+c1; B só c6
        mk("b9", "Senti muita falta da conviv\xEAncia", ["c3"])
        // recorte extra de B
      ];
      return { id: uid4(), name: "Exemplo: codificador B (mesma entrevista)", method: "conteudo", text, codes, excerpts, categories: [], metatexts: [], updated: Date.now() };
    }
    function mkExample(method, name, text, codeDefs, exDefs, catDefs, metaDefs) {
      const codes = codeDefs.map((d3, i3) => ({ id: d3[0], name: d3[1], color: PALETTE2[i3 % PALETTE2.length], desc: d3[2] || "" }));
      const mk = (id, sub, codeIds, memo = "") => {
        const start = text.indexOf(sub);
        return { id, start: start < 0 ? 0 : start, end: start < 0 ? 0 : start + sub.length, text: sub, codeIds, memo };
      };
      const excerpts = exDefs.map((d3) => mk(d3[0], d3[1], d3[2], d3[3] || ""));
      const categories = catDefs.map((d3) => ({ id: d3[0], name: d3[1], tipo: d3[2] || "emergente", desc: d3[3] || "", codeIds: d3[4] }));
      const metatexts = metaDefs.map((d3) => ({ id: d3[0], title: d3[1], categoryId: d3[2], body: d3[3] }));
      return { id: uid4(), name, method, isExample: true, text, codes, excerpts, categories, metatexts, updated: Date.now() };
    }
